<body>
<h1>Sudoku</h1>
<p class="subtitle">Inserisci le cifre da 1 a 9 per completare la griglia</p>
<div id="board"></div>
<div class="controls">
<button onclick="newGame()">Nuova Partita</button>
<button onclick="clearCell()">Cancella</button>
</div>
<div class="numpad" id="numpad"></div>
<div class="difficulty">
<label for="diff">Difficoltà:</label>
<select id="diff">
<option value="easy">Facile</option>
<option value="medium" selected>Media</option>
<option value="hard">Difficile</option>
</select>
</div>
<div id="timer">00:00</div>
<div id="message"></div>

<script>
const EMPTY=0;
let board=[],solution=[],fixed=[],selectedCell=null,timerInterval=null,seconds=0,won=false;

function init(){
  const pad=document.getElementById('numpad');
  for(let i=1;i<=9;i++){
    const b=document.createElement('button');
    b.textContent=i;
    b.onclick=()=>inputNumber(i);
    pad.appendChild(b);
  }
  const e=document.createElement('button');
  e.className='erase';e.textContent='⌫';
  e.onclick=()=>clearCell();
  pad.appendChild(e);
  newGame();
}

function newGame(){
  won=false;
  seconds=0;
  document.getElementById('message').textContent='';
  document.getElementById('message').className='';
  clearInterval(timerInterval);
  timerInterval=setInterval(()=>{
    if(!won){
      seconds++;
      const m=String(Math.floor(seconds/60)).padStart(2,'0');
      const s=String(seconds%60).padStart(2,'0');
      document.getElementById('timer').textContent=m+':'+s;
    }
  },1000);
  generatePuzzle();
  renderBoard();
}

function generatePuzzle(){
  solution=Array.from({length:9},()=>Array(9).fill(EMPTY));
  fillGrid(solution);
  board=solution.map(r=>[...r]);
  fixed=Array.from({length:9},()=>Array(9).fill(false));
  const diff=document.getElementById('diff').value;
  let toRemove;
  if(diff==='easy')toRemove=35;
  else if(diff==='medium')toRemove=45;
  else toRemove=55;
  const positions=[];
  for(let r=0;r<9;r++)for(let c=0;c<9;c++)positions.push([r,c]);
  shuffle(positions);
  let removed=0;
  for(const[r,c]of positions){
    if(removed>=toRemove)break;
    const backup=board[r][c];
    board[r][c]=EMPTY;
    if(countSolutions(board.map(r=>[...r]),0)<=1){
      removed++;
    }else{
      board[r][c]=backup;
    }
  }
  for(let r=0;r<9;r++)for(let c=0;c<9;c++){
    if(board[r][c]!==EMPTY)fixed[r][c]=true;
    else fixed[r][c]=false;
  }
}

function countSolutions(grid,count){
  for(let r=0;r<9;r++)for(let c=0;c<9;c++){
    if(grid[r][c]===EMPTY){
      for(let v=1;v<=9;v++){
        if(isValidPlacement(grid,r,c,v)){
          grid[r][c]=v;
          count=countSolutions(grid,count);
          if(count>=2)return 2;
          grid[r][c]=EMPTY;
        }
      }
      return count;
    }
  }
  return count+1;
}

function isValidPlacement(grid,row,col,num){
  for(let i=0;i<9;i++){
    if(grid[row][i]===num)return false;
    if(grid[i][col]===num)return false;
  }
  const br=Math.floor(row/3)*3,bc=Math.floor(col/3)*3;
  for(let r=br;r<br+3;r++)for(let c=bc;c<bc+3;c++){
    if(grid[r][c]===num)return false;
  }
  return true;
}

function fillGrid(grid){
  for(let r=0;r<9;r++)for(let c=0;c<9;c++){
    if(grid[r][c]===EMPTY){
      const nums=[1,2,3,4,5,6,7,8,9];
      shuffle(nums);
      for(let v of nums){
        if(isValidPlacement(grid,r,c,v)){
          grid[r][c]=v;
          if(fillGrid(grid))return true;
          grid[r][c]=EMPTY;
        }
      }
      return false;
    }
  }
  return true;
}

function shuffle(arr){
  for(let i=arr.length-1;i>0;i--){
    const j=Math.floor(Math.random()*(i+1));
    [arr[i],arr[j]]=[arr[j],arr[i]];
  }
  return arr;
}

function renderBoard(){
  const boardEl=document.getElementById('board');
  boardEl.innerHTML='';
  for(let r=0;r<9;r++){
    for(let c=0;c<9;c++){
      const cell=document.createElement('div');
      cell.className='cell';
      cell.dataset.row=r;
      cell.dataset.col=c;
      if(fixed[r][c]){
        cell.classList.add('fixed');
        cell.textContent=board[r][c];
      }else if(board[r][c]!==EMPTY){
        cell.textContent=board[r][c];
      }
      cell.addEventListener('click',()=>selectCell(r,c));
      boardEl.appendChild(cell);
    }
  }
  updateHighlights();
}

function selectCell(r,c){
  if(won)return;
  selectedCell={r,c};
  updateHighlights();
}

function updateHighlights(){
  const cells=document.querySelectorAll('.cell');
  cells.forEach(cell=>{
    cell.classList.remove('selected','highlighted','same-number','error');
  });
  if(selectedCell===null)return;
  const{r,c}=selectedCell;
  const selVal=board[r][c];
  cells.forEach(cell=>{
    const cr=+cell.dataset.row;
    const cc=+cell.dataset.col;
    if(cr===r&&cc===c){
      cell.classList.add('selected');
    }else if(cr===r||cc===c||(Math.floor(cr/3)===Math.floor(r/3)&&Math.floor(cc/3)===Math.floor(c/3))){
      cell.classList.add('highlighted');
    }
    if(selVal!==EMPTY&&board[cr][cc]===selVal&&(cr!==r||cc!==c)){
      cell.classList.add('same-number');
    }
  });
  checkErrors();
}

function checkErrors(){
  const cells=document.querySelectorAll('.cell');
  cells.forEach(cell=>{
    const cr=+cell.dataset.row;
    const cc=+cell.dataset.col;
    if(board[cr][cc]!==EMPTY&&!fixed[cr][cc]){
      board[cr][cc]=board[cr][cc];
      if(!isValidPlacement(board,cr,cc,board[cr][cc])){
        cell.classList.add('error');
      }
    }
  });
}

function inputNumber(num){
  if(won||selectedCell===null)return;
  const{r,c}=selectedCell;
  if(fixed[r][c])return;
  board[r][c]=num;
  refreshCell(r,c);
  updateHighlights();
  checkWin();
}

function clearCell(){
  if(won||selectedCell===null)return;
  const{r,c}=selectedCell;
  if(fixed[r][c])return;
  board[r][c]=EMPTY;
  refreshCell(r,c);
  updateHighlights();
}

function refreshCell(r,c){
  const idx=r*9+c;
  const cell=document.querySelectorAll('.cell')[idx];
  cell.textContent=board[r][c]||'';
  cell.classList.remove('error');
  if(fixed[r][c]){
    cell.classList.add('fixed');
    cell.textContent=board[r][c];
  }else if(board[r][c]!==EMPTY){
    cell.classList.remove('fixed');
    cell.textContent=board[r][c];
  }else{
    cell.classList.remove('fixed');
  }
}

function checkWin(){
  for(let r=0;r<9;r++)for(let c=0;c<9;c++){
    if(board[r][c]===EMPTY)return;
    if(!isValidPlacement(board,r,c,board[r][c]))return;
  }
  won=true;
  clearInterval(timerInterval);
  const msg=document.getElementById('message');
  const m=String(Math.floor(seconds/60)).padStart(2,'0');
  const s=String(seconds%60).padStart(2,'0');
  msg.textContent='🎉 Complimenti! Hai completato il Sudoku in '+m+':'+s+'!';
  msg.className='win';
}

document.addEventListener('keydown',e=>{
  if(won)return;
  const key=e.key;
  if(key>='1'&&key<='9'){
    inputNumber(+key);
  }else if(key==='Backspace'||key==='Delete'){
    clearCell();
  }else if(key==='ArrowUp'||key==='ArrowDown'||key==='ArrowLeft'||key==='ArrowRight'){
    e.preventDefault();
    if(selectedCell===null){selectCell(0,0);return;}
    let{r,c}=selectedCell;
    if(key==='ArrowUp')r=Math.max(0,r-1);
    if(key==='ArrowDown')r=Math.min(8,r+1);
    if(key==='ArrowLeft')c=Math.max(0,c-1);
    if(key==='ArrowRight')c=Math.min(8,c+1);
    selectCell(r,c);
  }
});

init();
</script>
</body>
</html>
